mapper.sql:
P.DELETED_FLAG = 0
AND (P.NAME LIKE '%' || #{keyword} || '%' OR P.EXTERNAL_ID LIKE '%' || #{keyword} || '%' OR P.ORGANIZATION LIKE '%' || #{keyword} || '%' OR P.OCCUPATION LIKE '%' || #{keyword} || '%')
AND P.ID IN ( SELECT PT.PERSON_ID FROM PT_PERSON_TAG PT WHERE PT.STATUS = 'APPROVED' AND PT.TAG_ID IN
#{tagId}
GROUP BY PT.PERSON_ID
HAVING COUNT(DISTINCT PT.TAG_ID) = #{tagCount}
)

mapper.update:
UPDATE PT_PERSON SET NAME = #{name}, GENDER = #{gender}, ORGANIZATION = #{organization},
    OCCUPATION = #{occupation}, ADDRESS = #{address}, REMARK = #{remark},
    SOURCE_UPDATED_AT = #{sourceUpdatedAt}, DELETED_FLAG = #{deleted}, UPDATED_AT = #{updatedAt}
WHERE ID = #{id}

mapper.select:
SELECT ID, EXTERNAL_ID, NAME, GENDER, ORGANIZATION, OCCUPATION, ADDRESS, REMARK,
       SOURCE_UPDATED_AT, DELETED_FLAG AS DELETED, CREATED_AT, UPDATED_AT
FROM PT_PERSON WHERE ID = #{id}

SELECT ID, EXTERNAL_ID, NAME, GENDER, ORGANIZATION, OCCUPATION, ADDRESS, REMARK,
       SOURCE_UPDATED_AT, DELETED_FLAG AS DELETED, CREATED_AT, UPDATED_AT
FROM PT_PERSON WHERE EXTERNAL_ID = #{externalId}
